#include <iostream>
#include <vector>
#include <string>

using namespace std;

int N;
vector<string> grid;

string solve(int r, int c, int size) {
    char v = grid[r][c];
    bool same = true;

    for (int i = r; i < r + size && same; ++i) {
        for (int j = c; j < c + size; ++j) {
            if (grid[i][j] != v) {
                same = false;
                break;
            }
        }
    }

    if (same) {
        return string(1, v);
    }

    int half = size / 2;
    string result;
    result += "(";
    result += solve(r, c, half);
    result += solve(r, c + half, half);
    result += solve(r + half, c, half);
    result += solve(r + half, c + half, half);
    result += ")";

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;
    grid.resize(N);

    for (int i = 0; i < N; ++i) {
        cin >> grid[i];
    }

    cout << solve(0, 0, N) << '\n';

    return 0;
}
